const h = String((msg.req.headers || {}).authorization || '');
msg.params = [h.replace(/^Bearer\s+/i, '').trim()];
return msg;

const row = (msg.payload && msg.payload[0]) || null;
// Sem linha = token invalido ou expirado. 401 para o app saber que a
// sessao morreu, em vez de tratar como falha de rede e insistir.
if (!row) { msg.statusCode = 401; msg.payload = { error: 'unauthorized' }; return msg; }
msg.statusCode = 200;
msg.payload = row;
return msg;
